{
  "technical_and_design_decisions": [
    "Target platform is an existing Spring XD-style distributed runtime; processors and sinks are delivered as deployable stream modules registered in the module registry, not as changes to the core container.",
    "U2 (Python): adopt a process-based integration (launch CPython via ProcessBuilder, exchange data over stdin/stdout with a defined line/record marshalling format) rather than Jython, so that native libraries such as NumPy/pandas are usable; a short spike will confirm feasibility before implementation.",
    "U3 (R): adopt a process-based integration (Rscript over stdin/stdout) as the default; rJava/Renjin evaluated in a spike and kept as a pluggable alternative binding only if the spike shows clear benefit, to keep consistency with the Python processor design.",
    "U4 (Hive): sink writes data files to HDFS using the Hadoop HDFS client and registers/updates external Hive tables via Hive metastore/JDBC; Kerberos-secured clusters supported through JAAS/keytab configuration.",
    "U6-U8 (security): use Spring Security for admin endpoint authentication/authorization; security definitions map REST API entities to role/group policies; ACL model supports create/destroy/view permissions on streams with default of all authenticated users; ACLs and security definitions are persisted in the existing distributed coordination store (ZooKeeper) so shell, REST API, and Admin UI share one policy source enforced server-side.",
    "U1 is documentation-led: document existing SSL/HTTPS and Basic authentication configuration properties for admin endpoints with verified examples; minimal code changes (only configuration property fixes if gaps are found).",
    "U5 upgrade aligns the whole dependency tree to Spring Framework 4.1.1 (milestone) via the build's dependency management; deprecated API usage is migrated rather than shimmed.",
    "All features include reference documentation (asciidoc) and runnable samples as part of done."
  ],
  "assumptions": [
    "An existing Spring XD-like codebase, Gradle build, CI pipeline, and automated test infrastructure are already in place; no greenfield project setup is required.",
    "A Hadoop/Hive test cluster (including a Kerberos-secured instance) is available for U4 integration testing.",
    "Python (2.7/3.x) and R runtimes are installed on the hosts used for U2/U3 integration tests.",
    "Estimates represent the hands-on development effort of a single experienced developer familiar with the codebase, and include design, implementation, unit/integration testing, and documentation, but exclude elapsed calendar time, vacations, and external dependencies' wait time.",
    "The specification's background references to Spring Framework 6.0/Java 17 are generic context; this increment follows U5 and targets Spring Framework 4.1.1 on the existing Java baseline of the product.",
    "Admin UI is an existing Angular-based application; U8 changes are incremental to it and require no new UI design work.",
    "U1 requires no new security features in code beyond documenting and verifying existing configuration knobs.",
    "External milestone dependencies (Spring 4.1.1, Hadoop/Hive, Python, R) are stable enough that integration issues can be fixed within the estimated effort."
  ],
  "activities": [
    {
      "activity_id": "1.1",
      "activity_name": "Review admin endpoint security configuration options",
      "activity_description": "U1: Inventory existing configuration properties for SSL/HTTPS and Basic authentication on administration endpoints; identify and fix minor configuration gaps.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "1.2",
      "activity_name": "Author SSL/HTTPS and Basic auth documentation",
      "activity_description": "U1: Write reference documentation and configuration examples (property files, yml) for securing admin endpoints with SSL/HTTPS and Basic authentication.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "1.3",
      "activity_name": "Validate documented security configurations",
      "activity_description": "U1: Manually verify each documented configuration variant end-to-end against a running admin server.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "2.1",
      "activity_name": "Spike: Python integration approach",
      "activity_description": "U2: Investigate native (Jython) versus stdin/stdout process-based integration; build a small prototype of the chosen approach and record findings.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "2.2",
      "activity_name": "Design Python processor module contract",
      "activity_description": "U2: Define module options (script location, interpreter path, environment), input/output marshalling format, and process lifecycle/error handling.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "2.3",
      "activity_name": "Implement Python processor module",
      "activity_description": "U2: Implement the processor: process launch/management, data marshalling over stdin/stdout, error propagation, and module metadata.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "2.4",
      "activity_name": "Unit tests for Python processor",
      "activity_description": "U2: Unit tests covering marshalling, process lifecycle, and failure modes.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "2.5",
      "activity_name": "Integration tests for Python processor",
      "activity_description": "U2: End-to-end tests of the Python processor inside deployed streaming pipelines.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "2.6",
      "activity_name": "Python processor documentation and samples",
      "activity_description": "U2: Reference documentation and example streams using the Python processor.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "3.1",
      "activity_name": "Spike: R integration approach",
      "activity_description": "U3: Evaluate rJava versus Renjin versus Rscript process-based integration; prototype the chosen approach and record findings.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "3.2",
      "activity_name": "Implement R processor module",
      "activity_description": "U3: Implement the R processor module with the same contract style as the Python processor (options, marshalling, lifecycle).",
      "most_likely_effort": 56
    },
    {
      "activity_id": "3.3",
      "activity_name": "Unit tests for R processor",
      "activity_description": "U3: Unit tests covering marshalling, script execution, and failure modes.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "3.4",
      "activity_name": "Integration tests for R processor",
      "activity_description": "U3: End-to-end tests of the R processor within streaming pipelines.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "3.5",
      "activity_name": "R processor documentation and samples",
      "activity_description": "U3: Reference documentation and example streams using the R processor.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "4.1",
      "activity_name": "Design Hive sink",
      "activity_description": "U4: Design data layout on HDFS, file formats, partitioning, table registration, and Kerberos support options.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "4.2",
      "activity_name": "Implement Hive sink module",
      "activity_description": "U4: Implement the sink: HDFS writes, batching/rollover, Hive external table registration, and module metadata.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "4.3",
      "activity_name": "Unit tests for Hive sink",
      "activity_description": "U4: Unit tests for path resolution, batching, and table DDL generation.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "4.4",
      "activity_name": "Integration tests against Hadoop/Hive cluster",
      "activity_description": "U4: Integration tests writing to HDFS and querying via Hive, including a Kerberos-secured cluster.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "4.5",
      "activity_name": "Hive sink documentation",
      "activity_description": "U4: Reference documentation and sample stream definitions for the Hive sink.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "5.1",
      "activity_name": "Upgrade build to Spring Framework 4.1.1",
      "activity_description": "U5: Update dependency management to Spring Framework 4.1.1 milestone and align related dependency versions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "5.2",
      "activity_name": "Fix API deprecations and incompatibilities",
      "activity_description": "U5: Migrate code affected by deprecated/changed Spring APIs, including SpEL compilation-related adjustments.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "5.3",
      "activity_name": "Regression testing for Spring upgrade",
      "activity_description": "U5: Run full automated regression suites, investigate and fix regressions caused by the upgrade.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "6.1",
      "activity_name": "Design entity security definition model",
      "activity_description": "U6: Design the model mapping REST API entities to group/role access policies, including storage schema and defaults.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "6.2",
      "activity_name": "Implement security definitions storage and management",
      "activity_description": "U6: Implement persistence (shared coordination store) and management API for security definitions.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "6.3",
      "activity_name": "Enforce role/group authorization on REST endpoints",
      "activity_description": "U6: Wire Spring Security checks so each REST API entity enforces its configured group/role policy.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "6.4",
      "activity_name": "Authorization tests for REST API policies",
      "activity_description": "U6: Unit and integration tests covering allowed/denied access per entity and role.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "6.5",
      "activity_name": "Security definitions documentation",
      "activity_description": "U6: Document how to define and manage entity-specific access policies.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "7.1",
      "activity_name": "Design DSL shell ACL model",
      "activity_description": "U7: Design ACL model for stream create/destroy/view operations with default of all authenticated users.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "7.2",
      "activity_name": "Implement ACL persistence and evaluation service",
      "activity_description": "U7: Implement shared ACL storage and the permission evaluation service used by all access paths.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "7.3",
      "activity_name": "Integrate ACL checks into DSL shell commands",
      "activity_description": "U7: Enforce ACLs on shell commands (stream create/destroy/list/view) with clear denial messages.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "7.4",
      "activity_name": "Tests for shell ACLs",
      "activity_description": "U7: Unit and integration tests for ACL enforcement and defaults via the DSL shell.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "7.5",
      "activity_name": "Shell ACL documentation",
      "activity_description": "U7: Document shell ACL configuration with examples.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "8.1",
      "activity_name": "Enforce ACLs on Admin UI backend endpoints",
      "activity_description": "U8: Apply the shared ACL evaluation service to the backend endpoints backing the Admin UI.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "8.2",
      "activity_name": "Update Admin UI for ACL restrictions",
      "activity_description": "U8: Hide/disable restricted actions in the Admin UI based on the current user's permissions.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "8.3",
      "activity_name": "Tests for Admin UI ACLs",
      "activity_description": "U8: Backend and UI-level tests verifying ACL enforcement in the Admin UI.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "8.4",
      "activity_name": "Admin UI ACL documentation",
      "activity_description": "U8: Document Admin UI access restriction behavior and configuration.",
      "most_likely_effort": 8
    },
